<!-- wp:wdl/lw-step-1 {"bgGradient":"#2f3437","filterOpacity":0.08,"titleText":"\u003cspan data-lw_font_set=\u0022Shippori Mincho\u0022 class=\u0022custom-font-settings\u0022\u003e当日の流れ\u003c/span\u003e","ulMaxWidth":760,"fontH3":"Shippori Mincho","fontWeightH3":"500","colorLiSvg":"#a9884b"} -->
<div class="wp-block-wdl-lw-step-1 lw-step-1"><h2 class="lw-step-1__title"><span data-lw_font_set="Shippori Mincho" class="custom-font-settings">当日の流れ</span></h2><ul class="lw-step-1__inner" style="max-width:760px"><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">カウンセリング</h3><p data-lw_font_set="" style="font-weight:">どこが重いか、いつから続いているかを伺います。強さの好みもここで決めます。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">首・肩・デコルテ</h3><p data-lw_font_set="" style="font-weight:">鎖骨のくぼみまで順に流します。こちらからお声がけはいたしません。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">ヘッドスパ</h3><p data-lw_font_set="" style="font-weight:">頭の側面から後頭部へ。オイルを使わないので髪は濡れません。眠っていただいて構いません。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">お茶をお出しします</h3><p data-lw_font_set="" style="font-weight:">急に起き上がらずに、ゆっくり戻していただきます。ご自宅でできるほぐし方もお伝えします。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li></ul><div class="lw-step-1__filter" style="background:#2f3437;opacity:0.08"></div></div>
<!-- /wp:wdl/lw-step-1 -->

