<!-- wp:wdl/lw-voice-1 {"h2FontSet":"Shippori Mincho","h2FontWeight":"500","h2TextColor":"#2f3437","nameBackgroundColor":"#2f3437","nameFontSet":"","h3TextColor":"#2f3437","h3FontSet":"Shippori Mincho","pTextColor":"#3a3733","pFontSet":"","backgroundColor":"#f4f1ec"} -->
<div class="wp-block-wdl-lw-voice-1 lw-voice-1" style="background-color:#f4f1ec"><h2 class="lw-voice-1__title" style="font-weight:500;color:#2f3437" data-lw_font_set="Shippori Mincho">お客様の声</h2><ul class="lw-voice-1__ul"><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">鎌倉市 50代 T様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">いちばん変わったのは、眠りでした。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">肩こりで通い始めましたが、施術の日の夜は朝まで起きません。静かで、話しかけられすぎないところも気に入っています。</p></div></li><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">横浜市 40代 N様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">顔のむくみが、首から来ていたと知りました。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">顔だけをほぐしても戻っていた理由が分かりました。鎖骨まで流していただいた翌朝は、輪郭が出ています。</p></div></li><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">藤沢市 30代 K様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">目の奥の重さが、その日のうちに取れます。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">一日中画面を見る仕事です。ヘッドスパの45分だけでも寄れるので、月に二度、昼休みに通っています。</p></div></li></ul></div>
<!-- /wp:wdl/lw-voice-1 -->

